// Synthetic input files, generated by code on every run. Nothing binary is
// checked in and no customer file is ever used.
import { minimalCfb, minimalXlsx } from '../../test/fixtures';

export const XLSX_PARTS = [
  '/_rels/.rels',
  '/xl/workbook.xml',
  '/xl/_rels/workbook.xml.rels',
  '/xl/worksheets/sheet1.xml',
  '/customXml/unknown.bin',
];

export const XLS_STREAMS = [
  { path: 'Workbook', size: 9 * 512 },
  { path: 'Small', size: 100 },
];

/** Compression methods of the entries, read from the local file headers. */
function localHeaderMethods(zip: Uint8Array): number[] {
  const view = new DataView(zip.buffer, zip.byteOffset, zip.byteLength);
  const methods: number[] = [];
  let offset = 0;
  while (offset + 30 <= zip.length && view.getUint32(offset, true) === 0x04034b50) {
    methods.push(view.getUint16(offset + 8, true));
    offset += 30 + view.getUint16(offset + 26, true) + view.getUint16(offset + 28, true) + view.getUint32(offset + 18, true);
  }
  return methods;
}

/** Minimal workbook. Guaranteed to contain deflate-compressed entries. */
export async function xlsx(): Promise<Uint8Array> {
  const bytes = await minimalXlsx();
  const methods = localHeaderMethods(bytes);
  if (!methods.includes(8)) throw new Error('fixture must contain at least one deflated entry');
  return bytes;
}

/** Minimal BIFF-style compound file: a "Workbook" stream and a mini-stream entry. */
export function xls(): Uint8Array {
  const big = new Uint8Array(9 * 512);
  for (let i = 0; i < big.length; i++) big[i] = (i * 31) & 0xff;
  const small = new Uint8Array(100);
  for (let i = 0; i < small.length; i++) small[i] = (i * 7) & 0xff;
  return minimalCfb(big, small);
}

/** First half of a valid workbook: the central directory is gone. */
export async function truncatedXlsx(): Promise<Uint8Array> {
  const bytes = await xlsx();
  return bytes.slice(0, bytes.length >> 1);
}

/**
 * Valid ZIP structure, but the compressed data of the first entry
 * ([Content_Types].xml, which open() must read) is overwritten.
 */
export async function corruptDataXlsx(): Promise<Uint8Array> {
  const bytes = await xlsx();
  const nameLength = new DataView(bytes.buffer, bytes.byteOffset).getUint16(26, true);
  const start = 30 + nameLength + 8;
  for (let i = start; i < start + 96; i++) bytes[i] = (bytes[i] ^ 0xa5 ^ (i * 13)) & 0xff;
  return bytes;
}

/** Central directory offsets and sizes replaced by out-of-range values. */
export async function corruptDirectoryXlsx(): Promise<Uint8Array> {
  const bytes = await xlsx();
  // End-of-central-directory record is the last 22 bytes (the fixture has no comment).
  const eocd = bytes.length - 22;
  for (let i = eocd + 8; i < eocd + 20; i++) bytes[i] = 0xff;
  return bytes;
}

export const emptyFile = (): Uint8Array => new Uint8Array(0);

export const textFile = (): Uint8Array => new TextEncoder().encode('This is plain text, not an Office file.\n');

/** Opens bytes with the built ESM bundle in Node (the same artefact the browser loads). */
export async function openInNode(bytes: Uint8Array) {
  const engine = await import(new URL('../../dist/bymoffice.esm.js', import.meta.url).href);
  return engine.open(bytes);
}

/** Reads every part of an opened OOXML package into plain number arrays. */
export async function readPartsInNode(bytes: Uint8Array): Promise<Record<string, number[]>> {
  const file = await openInNode(bytes);
  const out: Record<string, number[]> = {};
  for (const part of file.package.partNames()) out[part] = Array.from(await file.package.readPart(part));
  return out;
}
